 function share(){try{if(privateAssets(p).length){setShareURL('');setModal('share');return;}const url=new URL(location.href);url.hash='studio='+encodeProject({...studio.snapshot(),time:reduced?0:studio.time.current,paused:true});setShareURL(url.toString());setModal('share');}catch(e){notify(e instanceof Error?e.message:'Could not make this link.');}}
 async function exportPNG(){if(progress!==null)return;setProgress(0);try{const snapshot=studio.snapshot(),name=`stillwild-${snapshot.direction}-${width}x${width*9/16}.png`;await deliverArtwork(()=>png(snapshot,snapshot.time,width,reduced),blob=>download(blob,name));setDelivery({projectId:snapshot.id,appearance:projectAppearance(snapshot),kind:'PNG',name,frame:reduced?0:snapshot.time});setBackupDone(false);notify(`${width} × ${width*9/16} PNG download started. Artwork only.`);}catch(e){notify(e instanceof Error?e.message:'Image export failed.');}finally{setProgress(null);}}
 async function exportVideo(){if(progress!==null)return;const controller=new AbortController();abort.current=controller;setProgress(0);try{const snapshot=studio.snapshot();const result=await video(snapshot,reduced&&!videoMotion,setProgress,controller.signal,includeSound),name=`stillwild-${snapshot.direction}-${snapshot.duration}s-1080p-${includeSound?'with-sound':'silent'}.${result.extension}`;await deliverArtwork(async()=>result.blob,blob=>download(blob,name),controller.signal);setDelivery({projectId:snapshot.id,appearance:projectAppearance(snapshot),kind:'video',name});setBackupDone(false);notify(includeSound?'1080p loop download started with the chosen project sound.':'1080p silent loop download started.');}catch(e){notify(controller.signal.aborted?'Video export cancelled.':e instanceof Error?e.message:'Video export failed.');}finally{setProgress(null);abort.current=null;}}
